const outreachSubjects = [
  'quick question',
  'can i ask you something',
  'not sure who handles this',
  'random idea',
  'quick thought',
  'worth 5 minutes?',
  'one for you',
  'quick one',
  'not trying to sell you anything',
  "is this something you've considered?",
  'built something for electricians',
  'random question',
  'no pressure, just curious',
  'quick favour to ask',
  'saw this and thought of you',
  "figured i'd ask",
  'still curious',
  'just checking in',
  'one more thing',
  'had another thought',
  'following up on this',
  'worth a look?',
  'this might help',
  'came across something',
  'still relevant?',
  'did this land?',
  'wanted to add something',
  'different angle',
  'thought about this more',
  'forgot to mention',
  'one last thing',
  'before i leave you alone'
];

const ownEmails = [\your@email.com', \your@email.com'];

const results = [];

for (const item of $input.all()) {
  const email = item.json;

  // Debug: log all top-level keys so we can see the Gmail node output shape
  console.log('Gmail item keys: ' + Object.keys(email).join(', '));
  console.log('from=' + email.from + ' | From=' + email.From + ' | sender=' + email.sender);

  const subject = (email.subject || email.Subject || (email.payload?.headers?.find(h => h.name === 'Subject')?.value) || '').toLowerCase().replace(/^re:\s*/i, '').trim();

  const isOutreachReply = outreachSubjects.some(s => subject.includes(s));
  if (!isOutreachReply) { console.log('Not outreach reply, subject: ' + subject); continue; }

  // Try every possible location the From address could be
  const fromHeader = email.from || email.From || email.sender ||
    (email.payload?.headers?.find(h => h.name === 'From' || h.name === 'from')?.value) || '';
  console.log('fromHeader: ' + fromHeader);

  const senderEmailMatch = fromHeader.match(/<([^>]+)>/) || fromHeader.match(/([\w.+-]+@[\w.-]+\.[\w.]+)/);
  const senderEmail = senderEmailMatch ? senderEmailMatch[1].toLowerCase().trim() : fromHeader.toLowerCase().trim();
  console.log('senderEmail extracted: ' + senderEmail);
  if (!senderEmail) continue;

  const isOwnEmail = ownEmails.some(d => senderEmail === d);
  if (isOwnEmail) continue;

  const messageId = email.id || email.messageId || '';
  const body = email.text || email.snippet || '';
  const originalSubject = email.subject || email.Subject || (email.payload?.headers?.find(h => h.name === 'Subject')?.value) || '';

  results.push({ json: { senderEmail, subject: originalSubject, messageId, rawFrom: fromHeader, body } });
}

if (results.length === 0) throw new Error('No matching outreach replies found');
return results;

const results = [];

// Mark as Read overwrites item data — pull original parsed fields from Parse Reply node
const parsedItems = $('Parse Reply').all();

for (let i = 0; i < parsedItems.length; i++) {
  const { senderEmail, subject, messageId, rawFrom, body } = parsedItems[i].json;
  console.log('Processing senderEmail: ' + senderEmail);

  // Try email= param first (exact match)
  let contacts = [];
  let r1Raw = null;
  try {
    r1Raw = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://services.leadconnectorhq.com/contacts/?locationId=lRmpmIPQq1UG7nJr1LK5&email=' + encodeURIComponent(senderEmail),
      headers: { 'Authorization': 'Bearer YOUR_TOKEN_HERE', 'Version': '2021-07-28' },
      json: true
    });
    contacts = r1Raw.contacts || [];
    console.log('email= lookup for ' + senderEmail + ' → ' + contacts.length + ' results. raw keys: ' + Object.keys(r1Raw).join(','));
  } catch(e) {
    console.log('email= lookup error: ' + e.message);
  }

  if (contacts.length === 0) {
    try {
      const r2 = await this.helpers.httpRequest({
        method: 'GET',
        url: 'https://services.leadconnectorhq.com/contacts/?locationId=lRmpmIPQq1UG7nJr1LK5&query=' + encodeURIComponent(senderEmail),
        headers: { 'Authorization': 'Bearer YOUR_TOKEN_HERE', 'Version': '2021-07-28' },
        json: true
      });
      contacts = r2.contacts || [];
      console.log('query= lookup for ' + senderEmail + ' → ' + contacts.length + ' results');
    } catch(e) {
      console.log('query= lookup error: ' + e.message);
    }
  }

  if (contacts.length === 0) {
    console.log('Contact not found in GHL for: ' + senderEmail + ' — skipping');
    continue;
  }

  const contact = contacts[0];
  const contactId = contact.id;
  const nameParts = [contact.firstName, contact.lastName].filter(p => p && p.trim());
  const fullName = contact.contactName || (nameParts.length > 0 ? nameParts.join(' ') : senderEmail);
  const tags = contact.tags || [];
  console.log('Found contact: ' + fullName + ' | tags: ' + tags.join(','));

  // Only skip if already replied AND has no outreach tags (pure duplicate guard)
  const hasOutreach = tags.includes('outreach') || tags.includes('outreach-sent');
  if (tags.includes('replied') && !hasOutreach) {
    console.log('Already processed (non-outreach replied contact): ' + senderEmail + ' — skipping');
    continue;
  }

  // Add replied tag (safe to call even if already has it — GHL is idempotent)
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://services.leadconnectorhq.com/contacts/' + contactId + '/tags',
    headers: { 'Authorization': 'Bearer YOUR_TOKEN_HERE', 'Version': '2021-07-28', 'Content-Type': 'application/json' },
    body: { tags: ['replied'] },
    json: true
  });

  // Find opportunity and move stage
  const oppResp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://services.leadconnectorhq.com/opportunities/search?location_id=lRmpmIPQq1UG7nJr1LK5&contact_id=' + contactId + '&pipeline_id=z712pcy3WvLGf2xtIZgV',
    headers: { 'Authorization': 'Bearer YOUR_TOKEN_HERE', 'Version': '2021-07-28' },
    json: true
  });

  const opportunities = oppResp.opportunities || [];
  let opportunityId = null;

  if (opportunities.length > 0) {
    opportunityId = opportunities[0].id;
    await this.helpers.httpRequest({
      method: 'PUT',
      url: 'https://services.leadconnectorhq.com/opportunities/' + opportunityId,
      headers: { 'Authorization': 'Bearer YOUR_TOKEN_HERE', 'Version': '2021-07-28', 'Content-Type': 'application/json' },
      body: { pipelineStageId: '082e1052-b5c8-432d-aa17-53a92c5922b3' },
      json: true
    });
  } else {
    console.log('No opportunity found for contact: ' + contactId + ' — skipping stage move');
  }

  results.push({ json: { senderEmail, subject, body, messageId, contactId, fullName, opportunityId } });
}

if (results.length === 0) throw new Error('No contacts processed — check console logs above for details');
return results;

const results = [];
for (const item of $input.all()) {
  const body = item.json.body || '';
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.deepseek.com/chat/completions',
    headers: {
      'Authorization': 'Bearer YOUR_TOKEN_HERE',
      'Content-Type': 'application/json'
    },
    body: {
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: 'You are a sales reply classifier. Classify the reply into exactly one of these categories: Interested, Not Interested, Question, Out of Office, Unsubscribe, Other. Reply with only the category name, nothing else.' },
        { role: 'user', content: 'Reply body: ' + body }
      ],
      max_tokens: 10
    },
    json: true
  });
  const category = (response.choices?.[0]?.message?.content || 'Other').trim();
  results.push({ json: { ...item.json, category } });
}
return results;

const categoryMap = {
  'Interested': 'category-interested',
  'Not Interested': 'category-not-interested',
  'Question': 'category-question',
  'Out of Office': 'category-out-of-office',
  'Unsubscribe': 'category-unsubscribe',
  'Other': 'category-other'
};
return $input.all().map(item => ({
  json: { ...item.json, categoryTag: categoryMap[item.json.category] || 'category-other' }
}));

