const categoryToLabel = {
  'category-interested': 'outreach-interested',
  'category-not-interested': 'outreach-not-interested',
  'category-question': 'outreach-question',
  'category-out-of-office': 'outreach-out-of-office',
  'category-unsubscribe': 'outreach-unsubscribe',
  'category-other': 'outreach-other'
};

const results = [];
for (const item of $input.all()) {
  const messageId = item.json.messageId;
  const labelName = categoryToLabel[item.json.categoryTag] || 'outreach-other';

  try {
    // List labels
    const labelsResp = await this.helpers.httpRequestWithAuthentication.call(this, 'gmailOAuth2', {
      method: 'GET',
      url: 'https://gmail.googleapis.com/gmail/v1/users/me/labels',
      json: true
    });
    let labelId = (labelsResp.labels || []).find(l => l.name === labelName)?.id;

    // Create if missing
    if (!labelId) {
      const created = await this.helpers.httpRequestWithAuthentication.call(this, 'gmailOAuth2', {
        method: 'POST',
        url: 'https://gmail.googleapis.com/gmail/v1/users/me/labels',
        json: true,
        body: { name: labelName, labelListVisibility: 'labelShow', messageListVisibility: 'show' }
      });
      labelId = created.id;
    }

    // Apply to message
    if (labelId && messageId) {
      await this.helpers.httpRequestWithAuthentication.call(this, 'gmailOAuth2', {
        method: 'POST',
        url: 'https://gmail.googleapis.com/gmail/v1/users/me/messages/' + messageId + '/modify',
        json: true,
        body: { addLabelIds: [labelId] }
      });
      console.log('Applied label ' + labelName + ' to message ' + messageId);
    }
  } catch(e) {
    console.log('Gmail label error: ' + e.message);
  }

  results.push({ json: { ...item.json } });
}
return results;

// $input here = sheet rows (one per contact, in same order as Add Category Tag output)
// Add Category Tag output has the reply data (senderEmail, fullName, body, category, contactId)
const replyItems = $('Apply Gmail Label').all();
const sheetItems = $input.all();

return replyItems.map((replyItem, i) => {
  const reply = replyItem.json;
  // Match sheet row by index (same order), fall back to empty if missing
  const sheetRow = sheetItems[i]?.json || {};
  const fromEmail = sheetRow.from_email || 'manual outreach (not in sheet)';
  const mailboxSlot = sheetRow.mailbox_slot || 'N/A';
  const originalSubject = sheetRow.subject || sheetRow.Subject || reply.subject || '';
  return { json: { ...reply, fromEmail, mailboxSlot, originalSubject } };
});

